from z3 import *

# Number of vertices
N = 15

# Create boolean variables for edges
E = [[Bool(f"e_{i}_{j}") if i < j else False for j in range(N)] for i in range(N)]

# Helper to get edge variable
def edge(i, j):
    if i < j:
        return E[i][j]
    elif i > j:
        return E[j][i]
    else:
        return False

s = Solver()

# Girth >= 6 means no cycles of length 3, 4, 5
# No 3-cycles
for i in range(N):
    for j in range(i+1, N):
        for k in range(j+1, N):
            s.add(Not(And(edge(i, j), edge(j, k), edge(k, i))))

# No 4-cycles
for i in range(N):
    for j in range(i+1, N):
        for k in range(j+1, N):
            for l in range(k+1, N):
                # A 4-cycle on i, j, k, l can be formed in 3 ways
                s.add(Not(And(edge(i, j), edge(j, k), edge(k, l), edge(l, i))))
                s.add(Not(And(edge(i, j), edge(j, l), edge(l, k), edge(k, i))))
                s.add(Not(And(edge(i, k), edge(k, j), edge(j, l), edge(l, i))))

# No 5-cycles
import itertools
for p in itertools.combinations(range(N), 5):
    # For 5 vertices, there are 12 possible 5-cycles
    # We can just say that the number of edges among any 5 vertices is at most 4?
    # Wait, a 5-cycle has 5 edges. If there are 5 edges among 5 vertices, and no 3-cycles or 4-cycles, it must be a 5-cycle.
    # So we can just say the sum of edges among any 5 vertices is <= 4.
    # Let's verify: if 5 vertices have 5 edges, and max degree is 2 (if it's a cycle).
    # If there's a vertex with degree 3, the remaining 4 vertices have 2 edges, which means there's a 3-cycle or 4-cycle.
    # So any graph on 5 vertices with 5 edges contains a cycle. Since girth >= 6, it can't contain any cycle.
    # Thus, any 5 vertices can have at most 4 edges!
    # Wait, is this true? A tree on 5 vertices has 4 edges. Any additional edge creates a cycle.
    # The cycle must be of length <= 5.
    # So yes, any 5 vertices can have at most 4 edges!
    edges_in_p = []
    for i in range(5):
        for j in range(i+1, 5):
            edges_in_p.append(edge(p[i], p[j]))
    s.add(Sum([If(e, 1, 0) for e in edges_in_p]) <= 4)

# At least 23 edges
all_edges = []
for i in range(N):
    for j in range(i+1, N):
        all_edges.append(edge(i, j))
s.add(Sum([If(e, 1, 0) for e in all_edges]) >= 23)

# 4-colorable
C = [Int(f"c_{i}") for i in range(N)]
for i in range(N):
    s.add(C[i] >= 0, C[i] <= 3)
for i in range(N):
    for j in range(i+1, N):
        s.add(Implies(edge(i, j), C[i] != C[j]))

if s.check() == sat:
    m = s.model()
    edges = []
    for i in range(N):
        for j in range(i+1, N):
            if is_true(m[E[i][j]]):
                edges.append((i, j))
    print("SAT")
    print(edges)
else:
    print("UNSAT")

from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
import itertools

N = 15
E = {}
var_counter = 1

for i in range(N):
    for j in range(i+1, N):
        E[(i, j)] = var_counter
        var_counter += 1

solver = Glucose4()

# No 3-cycles: any 3 vertices have <= 2 edges
for p in itertools.combinations(range(N), 3):
    edges = [E[(p[0], p[1])], E[(p[0], p[2])], E[(p[1], p[2])]]
    # At least one edge is false
    solver.add_clause([-e for e in edges])

# No 4-cycles: any 4 vertices have <= 3 edges
# Wait, a 4-cycle has 4 edges. If we just forbid 4-cycles:
for p in itertools.combinations(range(N), 4):
    # 4-cycles on these 4 vertices
    # (0,1,2,3) -> edges: (0,1), (1,2), (2,3), (0,3)
    c1 = [E[(p[0], p[1])], E[(p[1], p[2])], E[(p[2], p[3])], E[(p[0], p[3])]]
    c2 = [E[(p[0], p[1])], E[(p[1], p[3])], E[(p[2], p[3])], E[(p[0], p[2])]]
    c3 = [E[(p[0], p[2])], E[(p[1], p[2])], E[(p[1], p[3])], E[(p[0], p[3])]]
    solver.add_clause([-e for e in c1])
    solver.add_clause([-e for e in c2])
    solver.add_clause([-e for e in c3])

# No 5-cycles
for p in itertools.combinations(range(N), 5):
    # 5-cycles on these 5 vertices
    # There are 4! / 2 = 12 such cycles
    for perm in itertools.permutations(p[1:]):
        cycle_verts = (p[0],) + perm
        cycle_edges = []
        for i in range(5):
            u, v = cycle_verts[i], cycle_verts[(i+1)%5]
            if u > v: u, v = v, u
            cycle_edges.append(E[(u, v)])
        solver.add_clause([-e for e in cycle_edges])

# At least 23 edges
all_edges = [E[(i, j)] for i in range(N) for j in range(i+1, N)]
cnf = CardEnc.atleast(lits=all_edges, bound=23, encoding=EncType.seqcounter, vpool=None)
for clause in cnf.clauses:
    solver.add_clause(clause)

# 4-colorable
# Variables for colors: C_{i, c}
C = {}
for i in range(N):
    for c in range(4):
        C[(i, c)] = var_counter
        var_counter += 1

for i in range(N):
    # At least one color
    solver.add_clause([C[(i, c)] for c in range(4)])
    # At most one color
    for c1 in range(4):
        for c2 in range(c1+1, 4):
            solver.add_clause([-C[(i, c1)], -C[(i, c2)]])

for i in range(N):
    for j in range(i+1, N):
        for c in range(4):
            # If edge exists, colors must be different
            solver.add_clause([-E[(i, j)], -C[(i, c)], -C[(j, c)]])

if solver.solve():
    model = solver.get_model()
    edges = []
    for i in range(N):
        for j in range(i+1, N):
            if model[E[(i, j)] - 1] > 0:
                edges.append((i, j))
    print("SAT")
    print(edges)
else:
    print("UNSAT")
